/* ONC RPC scanner-evaluation fixture (MFI-21.6). */
enum kv_status {
    KV_OK = 0,
    KV_NOT_FOUND = 1,
    KV_ERROR = 1
};

struct kv_entry {
    string key<256>;
    opaque value<1024>;
};

program KV_PROG {
    version KV_VERS {
        void KV_NULL(void) = 0;
        kv_status KV_PUT(kv_entry) = 1;
    } = 1;
} = 0x20000001;
